/* multi
 * line
 * comment */

{
  // User-level Claude Code configuration (JSONC comment tolerance)
  "model": "claude-sonnet-4-5",
  "permissions": {
    "allow": ["Read", "Grep", "Glob"],
  },
  "env": {
    "ANTHROPIC_API_KEY": "TEST_SYNTHETIC_API_KEY_PLACEHOLDER"
  },
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "~/.claude/hooks/check-bash.sh",
            "timeout": 15
          }
        ]
      }
    ]
  }
}

{
  "mcpServers": {
    "memory": {
      "command": "npx",
      "args": ["-y", "@modelcontextprotocol/server-memory"],
      "env": {
        "MEMORY_STORAGE_PATH": "/tmp/claude-memory"
      }
    },
    "docs-search": {
      "type": "http",
      "url": "https://docs.example.test/mcp",
      "env": {
        "DOCS_ACCESS_TOKEN": "TEST_SYNTHETIC_TOKEN_PLACEHOLDER"
      }
    }
  }
}

{
  "permissions": {
    "allow": ["Bash(npm test)"]
  }
}

{
  "enabledMcpjsonServers": ["postgres"]
}

{
  "mcpServers": {
    "postgres": {
      "command": "npx",
      "args": ["-y", "@modelcontextprotocol/server-postgres"],
      "env": {
        "PGPASSWORD": "TEST_SYNTHETIC_DB_PASS_PLACEHOLDER"
      }
    },
    "unapproved-analytics": {
      "type": "sse",
      "url": "https://analytics.example.test/sse"
    }
  }
}

{
  "name": "legacy-helper",
  "version": "0.9.0",
  "description": "Disabled legacy plugin that should be inactive"
}

{
  "name": "team-toolkit",
  "version": "1.1.0",
  "description": "Older cached version of team-toolkit"
}

{
  "name": "team-toolkit",
  "version": "1.2.0",
  "description": "Shared engineering skills, agents, commands, hooks, and MCP tools"
}

{
  "mcpServers": {
    "acme-tracker": {
      "command": "node",
      "args": ["${CLAUDE_PLUGIN_ROOT}/mcp/tracker.js"],
      "env": {
        "ACME_TRACKER_SECRET": "TEST_SYNTHETIC_PLUGIN_SECRET"
      }
    }
  }
}

{
  "hooks": {
    "PostToolUse": [
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "${CLAUDE_PLUGIN_ROOT}/scripts/post-edit-lint.sh",
            "timeout": 20
          }
        ]
      }
    ]
  }
}

{
  "version": 2,
  "plugins": {
    "team-toolkit@acme-marketplace": [
      {
        "scope": "user",
        "version": "1.2.0",
        "installPath": "~/.claude/plugins/cache/acme-marketplace/team-toolkit/1.2.0"
      }
    ],
    "legacy-helper@acme-marketplace": [
      {
        "scope": "user",
        "version": "0.9.0",
        "installPath": "~/.claude/plugins/cache/acme-marketplace/legacy-helper/0.9.0"
      }
    ]
  }
}

{
  "enabledPlugins": {
    "team-toolkit@acme-marketplace": true,
    "legacy-helper@acme-marketplace": false
  }
}

{
  "model": "claude-haiku-4-5",
  "enableAllProjectMcpServers": false
}

{
  "mcpServers": {
    "corp-gateway": {
      "type": "http",
      "url": "https://personal-override-attempt.example.test/v1"
    },
    "github": {
      "command": "npx",
      "args": ["-y", "@modelcontextprotocol/server-github", "--personal"]
    },
    "blocked-mcp": {
      "command": "npx",
      "args": ["-y", "@example/blocked-server"]
    }
  },
  "projects": {
    "~/repos/payments": {
      "mcpServers": {
        "github": {
          "command": "npx",
          "args": ["-y", "@modelcontextprotocol/server-github", "--payments-local"]
        }
      },
      "disabledMcpjsonServers": ["disabled-in-local"]
    }
  }
}

{
  "mcpServers": {
    "corp-gateway": {
      "type": "http",
      "url": "https://mcp.corp.example.test/v1"
    }
  }
}

{
  "model": "claude-opus-4-6",
  "deniedMcpServers": [
    {
      "serverName": "blocked-mcp"
    }
  ]
}

{
  "model": "claude-sonnet-4-5",
  "enableAllProjectMcpServers": true
}

{
  "enabledMcpjsonServers": ["stripe-sandbox"]
}

{
  "mcpServers": {
    "github": {
      "command": "npx",
      "args": ["-y", "@modelcontextprotocol/server-github", "--project-shared"]
    },
    "stripe-sandbox": {
      "type": "http",
      "url": "https://mcp.stripe-sandbox.example.test/v1"
    },
    "disabled-in-local": {
      "command": "node",
      "args": ["./scripts/optional-mcp.js"]
    },
    "self-approved-attempt": {
      "type": "sse",
      "url": "https://untrusted.example.test/sse"
    }
  }
}

{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "scripts/lint-command.sh",
            "timeout": 15
          }
        ]
      }
    ]
  }
}

{
  "hooks": {
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "/usr/local/bin/codex-session-check",
            "timeout": 10
          }
        ]
      }
    ]
  }
}

{
  "hooks": {
    "PostToolUse": [
      {
        "matcher": "Write",
        "hooks": [
          {
            "type": "command",
            "command": "swift format lint",
            "timeout": 20
          }
        ]
      }
    ]
  }
}

{
  "model": "claude-sonnet-4",
  "trusted_folders": [
    "~/repos/octocat-api",
    "~/repos/missing-ghost-repo"
  ],
  "github_token": "TEST_SYNTHETIC_COPILOT_TOKEN_PLACEHOLDER"
}

{
  "version": 1,
  "hooks": {
    "preToolUse": [
      {
        "type": "command",
        "bash": "./scripts/verify-tool.sh",
        "timeoutSec": 15
      }
    ]
  }
}

{
  "mcpServers": {
    "github-personal": {
      "type": "local",
      "command": "npx",
      "args": ["-y", "@github/mcp-server"],
      "tools": ["*"],
      "env": {
        "GITHUB_PERSONAL_ACCESS_TOKEN": "TEST_SYNTHETIC_COPILOT_PAT_PLACEHOLDER"
      }
    },
    "observability": {
      "type": "http",
      "url": "https://telemetry.personal.example.test/mcp",
      "tools": ["query_metrics", "list_alerts"],
      "headers": {
        "Authorization": "Bearer TEST_SYNTHETIC_COPILOT_BEARER"
      }
    },
    "legacy-db": {
      "type": "stdio",
      "command": "uvx",
      "args": ["mcp-legacy-db"],
      "enabled": false
    }
  }
}

{
  "theme": "dark",
  "hooks": {
    "sessionStart": [
      {
        "type": "command",
        "bash": "echo copilot-session-start",
        "timeoutSec": 10
      }
    ]
  }
}

{
  "version": 1,
  "hooks": {
    "postToolUse": [
      {
        "type": "command",
        "bash": "swift format lint Sources Tests",
        "timeoutSec": 20
      }
    ]
  }
}

{
  "mcpServers": {
    "observability": {
      "type": "http",
      "url": "https://telemetry.octocat-api.example.test/mcp",
      "tools": ["query_metrics", "trace_request"]
    }
  }
}

{
  "servers": {
    "observability": {
      "type": "http",
      "url": "https://telemetry.vscode-fallback.example.test/mcp"
    },
    "openapi-preview": {
      "type": "stdio",
      "command": "npx",
      "args": ["-y", "@acme/openapi-mcp"]
    }
  }
}

{
  "mcpServers": {
    "figma": {
      "command": "npx",
      "args": ["-y", "figma-developer-mcp", "--personal"],
      "env": {
        "FIGMA_ACCESS_TOKEN": "TEST_SYNTHETIC_CURSOR_FIGMA_TOKEN"
      }
    },
    "linear": {
      "url": "https://mcp.linear.example.test/sse",
      "headers": {
        "Authorization": "Bearer TEST_SYNTHETIC_CURSOR_LINEAR_TOKEN"
      }
    },
    "archived-mcp": {
      "command": "uvx",
      "args": ["mcp-archived"],
      "disabled": true
    }
  }
}

{
  "mcpServers": {
    "figma": {
      "command": "npx",
      "args": ["-y", "figma-developer-mcp", "--design-system"],
      "env": {
        "FIGMA_ACCESS_TOKEN": "TEST_SYNTHETIC_PROJECT_FIGMA_TOKEN"
      }
    },
    "storybook": {
      "command": "npx",
      "args": ["-y", "@storybook/mcp"]
    }
  }
}

{
  "name": "cloud-tools",
  "version": "1.4.0",
  "description": "Cloud deployment and log analysis tools",
  "contextFileName": "CLOUD.md",
  "mcpServers": {
    "cloud-logs": {
      "command": "node",
      "args": ["${extensionPath}/server.js"],
      "env": {
        "CLOUD_API_SECRET": "TEST_SYNTHETIC_EXT_SECRET_PLACEHOLDER"
      }
    },
    "docs": {
      "command": "node",
      "args": ["${extensionPath}/docs.js"]
    }
  }
}

{
  "hooks": {
    "AfterTool": [
      {
        "matcher": "mcp_cloud-logs_.*",
        "hooks": [
          {
            "type": "command",
            "command": "node ${extensionPath}/audit-hook.js",
            "timeout": 15000
          }
        ]
      }
    ]
  }
}

{
  "name": "disabled-ext",
  "version": "0.1.0",
  "description": "Disabled experimental extension"
}

{
  "cloud-tools": {
    "overrides": ["*"]
  },
  "disabled-ext": {
    "overrides": ["!*"]
  }
}

{
  // User Gemini CLI settings with JSONC comment
  "context": {
    "fileName": ["AGENTS.md", "GEMINI.md"]
  },
  "mcp": {
    "excluded": ["experimental-mcp"]
  },
  "mcpServers": {
    "docs": {
      "command": "npx",
      "args": ["-y", "@user/docs-mcp"],
      "env": {
        "DOCS_API_KEY": "TEST_SYNTHETIC_GEMINI_KEY_PLACEHOLDER"
      }
    },
    "experimental-mcp": {
      "url": "http://localhost:8090/sse"
    }
  },
  "hooks": {
    "BeforeTool": [
      {
        "matcher": "run_shell_command",
        "hooks": [
          {
            "type": "command",
            "command": "scripts/check-shell.sh",
            "timeout": 30000
          }
        ]
      }
    ]
  }
}

{
  "security": {
    "disableYoloMode": true
  },
  "mcpServers": {
    "corp-policy": {
      "httpUrl": "https://policy.corp.example.test/mcp",
      "headers": {
        "Authorization": "Bearer TEST_SYNTHETIC_GEMINI_BEARER"
      }
    }
  }
}

{
  "general": {
    "vimMode": true
  },
  "mcpServers": {
    "docs": {
      "command": "npx",
      "args": ["-y", "@corp/default-docs-mcp"]
    }
  }
}

{
  "mcpServers": {
    "docs": {
      "command": "npx",
      "args": ["-y", "@storefront/docs-mcp"],
      "includeTools": ["search_docs"],
      "excludeTools": ["delete_doc"]
    }
  }
}

{
  // Hostile malformed JSON: stray closing brace and trailing garbage
  "model": "claude-sonnet",
  "broken": [1, 2,]
} trailing_garbage

{
  "model": "claude-sonnet",
  /* Unclosed block comment that runs to EOF
  "permissions": {
    "allow": ["Read"]
  }
}

{
  // Line comment before top-level properties
  "endpoint": "https://api.example.com/v1/*not-a-comment*///still-url",
  "apiKey": "TEST_SYNTHETIC_APIKEY_FOXTROT_06",
  "nested": {
    "access_token": "TEST_SYNTHETIC_TOKEN_ECHO_05",
    "clientSecret": "TEST_SYNTHETIC_SECRET_ALPHA_01",
    "db_password": "TEST_SYNTHETIC_PASSWORD_DELTA_04",
    "Authorization": "Bearer TEST_SYNTHETIC_BEARER_GOLF_07",
    "headers": {
      "X-Custom-Header": "TEST_SYNTHETIC_HEADER_CHARLIE_03",
      "Accept": "application/json",
    },
  },
  /* Multi-line block comment
     spanning two lines */
  "mcpServers": {
    "github": {
      "command": "npx",
      "args": ["-y", "@modelcontextprotocol/server-github",],
      "env": {
        "GITHUB_WORKSPACE_VAR": "TEST_SYNTHETIC_MCP_ENV_BRAVO_02",
        "PLAIN_FLAG": "TEST_SYNTHETIC_MCP_ENV_PLAIN_08",
      },
    },
  },
  "enabled": true,
  "retryCount": 3,
}

{
  "permissions": {
    "allow": ["Read"]
  }
}

{
  "mcpServers": {}
}

{
  "mcpServers": {
    "docs": {
      "command": "npx",
      "args": ["-y", "@acme/docs-mcp"]
    }
  }
}

{
  "mcpServers": {
    "postgres": {
      "command": "npx",
      "args": ["-y", "@modelcontextprotocol/server-postgres"],
      "env": {
        "POSTGRES_PASSWORD": "TEST_SYNTHETIC_WINDSURF_DB_PASSWORD"
      },
      "disabled": false
    },
    "internal-docs": {
      "serverUrl": "https://docs.windsurf.example.test/mcp",
      "headers": {
        "Authorization": "Bearer TEST_SYNTHETIC_WINDSURF_DOCS_TOKEN"
      },
      "disabledTools": ["delete_article"]
    },
    "disabled-tracer": {
      "command": "uvx",
      "args": ["mcp-tracer"],
      "disabled": true
    }
  }
}

